const NS = "agentnative.dbadmin.";
function hasStorage() {
    return typeof window !== "undefined" && !!window.localStorage;
}
/** Read and JSON-parse a namespaced key, returning `fallback` on any failure. */
export function getLS(key, fallback) {
    if (!hasStorage())
        return fallback;
    try {
        const raw = window.localStorage.getItem(`${NS}${key}`);
        if (raw === null)
            return fallback;
        return JSON.parse(raw);
    }
    catch {
        return fallback;
    }
}
/** JSON-serialize and write a namespaced key. No-op when storage is absent. */
export function setLS(key, value) {
    if (!hasStorage())
        return;
    try {
        window.localStorage.setItem(`${NS}${key}`, JSON.stringify(value));
    }
    catch {
        // Quota exceeded / disabled storage — silently ignore.
    }
}
/** Remove a namespaced key. */
export function removeLS(key) {
    if (!hasStorage())
        return;
    try {
        window.localStorage.removeItem(`${NS}${key}`);
    }
    catch {
        // ignore
    }
}
function gridKey(table) {
    return `grid.${table}`;
}
export function loadGridState(table) {
    return getLS(gridKey(table), {});
}
export function saveGridState(table, state) {
    setLS(gridKey(table), state);
}
